const initial={shopping:[{id:1,name:'עגבניות שרי',category:'ירקות ופירות',done:false},{id:2,name:'חלב שיבולת שועל',category:'מקרר',done:false},{id:3,name:'לחם מחמצת',category:'מאפים',done:true},{id:4,name:'אבוקדו',category:'ירקות ופירות',qty:2,done:false},{id:5,name:'ביצים',category:'מקרר וביצים',done:false},{id:6,name:'קפה',category:'מזווה',done:false}],tasks:[{id:1,title:'להשקות את העציצים',who:'רועי',when:'היום',done:false},{id:2,title:'להפעיל מכונת כביסה',who:'מאיה',when:'היום',done:false},{id:3,title:'לבחור ארוחה לערב',who:'ביחד',when:'בלי לחץ',done:false}]};let data;try{data=JSON.parse(localStorage.getItem('couple-demo-v1'))||structuredClone(initial)}catch{data=structuredClone(initial)};const save=()=>{if(window.CASA_CLOUD&&CASA_CLOUD.active)return CASA_CLOUD.onSave();try{localStorage.setItem('couple-demo-v1',JSON.stringify(data));return true}catch{toast('האחסון המקומי מלא. השינוי לא נשמר; נסו להסיר תמונה.');return false}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let token=sessionStorage.getItem('demo-invite')||crypto.randomUUID();sessionStorage.setItem('demo-invite',token);let revoked=sessionStorage.getItem('demo-revoked')==='true',accepted=sessionStorage.getItem('demo-accepted')==='true';const inviteUrl=()=>{const url=new URL('./',location.href);url.searchParams.set('invite',token);return url.href};const qrData=()=>`data:image/svg+xml;charset=utf-8,${encodeURIComponent(LocalQR.toSVG(inviteUrl()))}`;
function toast(text){$('.toast')?.remove();const d=document.createElement('div');d.className='toast';d.setAttribute('role','status');d.textContent=text;document.body.append(d);clearTimeout(toastTimer);toastTimer=setTimeout(()=>d.remove(),3500)}
function appHeader(){const me=myMember();const house=String((CASA_CLOUD.active?(CASA_CLOUD.housePending??(CASA_CLOUD.hh?.name||data.houseName)):data.houseName)||'').trim()||'הבית שלנו';return `<header class="top"><div class="side left">${avatarForMember(me)}<button class="gear" data-go="settings" aria-label="הגדרות">${gearIcon}</button></div><button class="brand centerbrand" data-go="home" aria-label="CASA בית">${casaLogo}<span class="brandtext"><span class="greeting">${esc(house)}</span></span></button><div class="side right"><button class="iconbtn tasksbtn" data-go="tasks" aria-label="מטלות">${icon('tasks')}</button></div></header>`}

function nav(){return `<nav class="nav" aria-label="ניווט ראשי">${[['home','home','היום'],['shopping','shop','קניות'],['meals','meal','תפריט'],['expenses','money','הוצאות']].map(([p,i,t])=>`<button data-go="${p}" class="${page===p||(p==='meals'&&(page==='meal'||page==='meal-edit'))?'active':''}">${icon(i)}${t}</button>`).join('')}</nav>`}

function taskRows(list=data.tasks){return list.length?list.map(t=>`<div class="task" data-task-row="${t.id}"><button class="check ${t.done?'done':''}" data-task="${t.id}" aria-label="${t.done?'ביטול השלמה: ':'השלמה: '}${esc(t.title)}" aria-pressed="${t.done}">${t.done?'✓':''}</button><div class="tasktext ${t.done?'completed':''}">${esc(t.title)}<small>${esc(t.when)} · ${t.done?'הושלמה':'פתוחה'}</small></div><div class="task-avatars" aria-label="אחראים">${avatarsForWho(t.who)}</div><button class="quiet task-del" data-del-task="${t.id}" aria-label="מחיקת ${esc(t.title)}">מחיקה</button></div>`).join(''):`<p class="empty listempty">${avoDeco('empty')}אין מטלות בתצוגה הזו. אפשר לבחור סינון אחר.</p>`}
function head(title,sub,action=''){return `<div class="head"><div><h1 class="withicon">${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`}
function welcome(){return `<div class="welcome welcome-a"><div class="welcome-a-logo">${casaLogo}</div><div class="welcome-a-hero" aria-hidden="true">${avocadoHero}</div><h1>הבית שלכם,<br>במקום אחד.</h1><p class="welcome-a-sub"><span class="welcome-a-line1">קניות · לו״ז · הוצאות · מטלות · ואפילו ארוחות</span><span class="welcome-a-line2">הכל מסונכרן בין כל בני הבית.</span></p><div class="welcome-a-actions"><button class="primary" id="welcome-create" data-go="login" data-intent="create">יצירת בית</button><button class="quiet welcome-a-account" data-go="login" data-intent="existing">כבר יש לי חשבון</button><button class="quiet welcome-a-demo" data-go="home">להציץ בהדגמה</button></div><p class="welcome-a-tag">לזוגות · למשפחות · לחברים</p></div>`}
function login(){return `<div class="center"><button class="back" data-go="welcome">→ בחזרה</button><div class="card"><div class="onboardingstep">מתחילים במקום קטן ומשותף</div><h1>היי, טוב שבאתם.</h1><p>בהמשך, לכל אחד יהיה חשבון אישי. כרגע אפשר להכיר את הבית בלי להירשם ובלי למסור פרטים.</p><button class="secondary nohover" disabled>כניסה באימייל — בחיבור החשבונות בהמשך</button><button class="primary" data-go="create">כניסה להדגמה</button><div class="notice">אין כאן כניסה אמיתית, סיסמאות או חשבון ענן. הנתונים נשמרים רק בדפדפן הזה.</div></div></div>`}
function create(){return `<div class="center"><button class="back" data-go="login">→ בחזרה</button><div class="card"><div class="onboardingstep">01 / הבית המשותף · הדגמה</div><h1>מקום קטן משותף.</h1><p>נתחיל עם בית לדוגמה, ונראה איך מצרפים חברים.</p><label for="house-name">איך נקרא לבית?</label><input id="house-name" value="${esc(data.houseName||'הבית שלנו')}" maxlength="60" style="margin-top:8px"><button class="primary" id="create-home">יצירת בית להדגמה</button><div class="footnote">השם יישמר מקומית בלבד. לא נוצר חשבון או בית בשרת.</div></div></div>`}
function invite(){return `<div class="center"><button class="back" data-go="settings">→ בחזרה להגדרות</button><div class="card"><div class="onboardingstep">02 / מצטרפים יחד · הדגמה</div><h1>כמה טלפונים.<br>בית אחד.</h1><p>כשאתם יחד, הכי פשוט לסרוק במצלמה הרגילה של הטלפון. מרחוק אפשר לשתף קישור.</p>${revoked?'<div class="notice">קישור ההדגמה בוטל בדפדפן הזה.</div><button class="primary" id="renew">יצירת QR הדגמה חדש</button>':`<img class="qr" src="${qrData()}" alt="QR אמיתי של קישור הזמנה מקומי להדגמה"><div class="notice">הדגמה מקומית — עדיין לא מחבר בין טלפונים. ה־QR פותח את אותה הדגמה בלבד, בלי לצרף חשבון או לסנכרן מידע. אין בו פרטי חשבון.</div><div class="link">${esc(inviteUrl())}</div><button class="primary" id="copy-invite">העתקת קישור לשיתוף</button><button class="secondary" data-go="accept">תצוגת קבלת ההזמנה</button><button class="quiet" id="revoke" style="margin-top:18px">ביטול ההזמנה בהדגמה</button>`}<div class="footnote">במוצר האמיתי: כניסה אישית ואישור מפורש, קישור חד־פעמי שפג לאחר 24 שעות וניתן לביטול. האבטחה הזו עדיין לא מחוברת לשרת.</div></div></div>`}
function accept(){return `<div class="center"><button class="back" data-go="invite">→ בחזרה להזמנה</button><div class="card"><div class="onboardingstep">תצוגה בלבד · אין התחברות בין מכשירים</div><h1>${accepted?'השלב הבא יהיה ביחד.':'הזמנה לבית לדוגמה'}</h1><p>${accepted?'אישור ההדגמה נרשם בדפדפן הזה בלבד. לא צורף אדם לבית אמיתי.':'במוצר המלא, כאן נכנסים לחשבון אישי, בודקים לאיזה בית הוזמנתם ומאשרים הצטרפות.'}</p><div class="notice">${revoked?'ההזמנה בוטלה בהדגמה.':accepted?'ההזמנה סומנה כנוצלה בהדגמה המקומית.':'בית לדוגמה · נתוני דוגמה בלבד'}</div>${!accepted&&!revoked?'<button class="primary" id="accept-demo">הדמיית אישור הצטרפות</button>':''}<button class="secondary" data-go="home">פתיחת הבית לדוגמה</button></div></div>`}


function tasks(){const filtered=data.tasks.filter(t=>(taskStatus==='all'||(taskStatus==='done'?t.done:!t.done))&&(taskOwner==='all'||t.who===taskOwner));return `<button class="back" data-go="home">→ בחזרה לבית</button>${head(`${avoDeco('tiny')}מטלות`,'רשימה קצרה של דברים לעשות בבית.')}<section class="card taskpage has-avo">${avoDeco('mark')}<div class="cardhead"><h2>בקצב של הבית</h2><span class="sub">${data.tasks.filter(t=>!t.done).length} פתוחות</span></div><div class="filtertabs" aria-label="סינון מצב">${[['all','הכול'],['open','פתוחות'],['done','הושלמו']].map(([v,l])=>`<button data-status="${v}" aria-pressed="${taskStatus===v}" class="${taskStatus===v?'selected':''}">${l}</button>`).join('')}</div><label class="selectlabel">לפי אחראי <select id="task-owner"><option value="all" ${taskOwner==='all'?'selected':''}>כולם</option>${whoOptions(taskOwner,true)}</select></label><div id="task-list">${taskRows(filtered)}</div><div class="addtask"><h3>עוד משהו קטן?</h3><input id="task-title" aria-label="שם מטלה חדשה" placeholder="מה צריך לעשות?" maxlength="100"><div class="taskfields"><label>מי מטפל?<select id="new-task-owner">${whoOptions(myMember().key,true)}</select></label><label>מתי?<select id="new-task-when"><option>היום</option><option>מחר</option><option>השבוע</option><option>בלי לחץ</option></select></label><button class="primary" id="add-task">הוספת מטלה</button></div></div>${T('','<div class="notice">השלמה, הוספה ומחיקה נשמרות מקומית בלבד.</div>')}</section>`}



