function closeCrop(){const modal=$('#crop-modal');if(modal)modal.hidden=true;if(cropState){try{cropState.image.close()}catch{}if(cropState.url)URL.revokeObjectURL(cropState.url)}cropState=null;const input=$('#profile-photo');if(input){input.value='';input.disabled=false}}
async function saveCrop(){if(!cropState)return;const out=document.createElement('canvas');out.width=out.height=512;const ctx=out.getContext('2d');const {image,scale,ox,oy}=cropState;const side=Math.min(image.width,image.height)/scale;const cx=image.width/2+ox,cy=image.height/2+oy;const sx=Math.max(0,Math.min(image.width-side,cx-side/2));const sy=Math.max(0,Math.min(image.height-side,cy-side/2));ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.beginPath();ctx.arc(256,256,256,0,Math.PI*2);ctx.clip();ctx.drawImage(image,sx,sy,side,side,0,0,512,512);const old=data.profiles.roei.photo;const stored=await storePhoto(out.toDataURL('image/jpeg',.9));data.profiles.roei.photo=stored;if(!save()){data.profiles.roei.photo=old;toast('אין מספיק מקום לשמירת התמונה');return}if(old&&old!==stored)dropPhoto(old);closeCrop();render();toast(T('התמונה נשמרה ומסונכרנת','התמונה נשמרה במכשיר בלבד'))}
