function toggleShopping(id){const t=data.shopping.find(t=>t.id===id);if(t.done&&data.shopping.some(other=>other.id!==id&&!other.done&&productKey(other.name)===productKey(t.name)&&other.unit===t.unit)){toast('המוצר כבר ברשימה הפתוחה. אפשר לעדכן שם את הכמות; הפריט שנקנה נשמר.');return}t.done=!t.done;save();render()}

function ensureMenu(){if(CASA_CLOUD.active){if(!data.menu)data.menu=[];if(!data.menuSeeded){data.menu=[...structuredClone(defaultMenuItems).filter(d=>!data.menu.some(m=>m.id===d.id)),...data.menu];data.menuSeeded=true;save()}if(!data.calendar)data.calendar=[]}else if(!data.menu||!data.menu.length){data.menu=structuredClone(defaultMenuItems);save()}if(!data.plannedMeals)data.plannedMeals=[];if(!data.freq)data.freq={};if(!data.calendar){data.calendar=seedCalendar();save()}}
function getMenu(){ensureMenu();return data.menu}
function getPlannedDishes(){ensureMenu();return data.plannedMeals.map(id=>data.menu.find(m=>m.id===id)).filter(Boolean)}
function seedCalendar(){const start=startOfWeek(localNoon(todayISO()));const iso=localIso;const at=n=>iso(addDays(start,n));return [
{id:'c1',date:todayISO(),title:'קניות קטנות',detail:'חלב וירקות',kind:'shop'},
{id:'c2',date:at(2),title:'ערב קטן בבית',detail:'בילוי בבית · דוגמה',kind:'date'},
{id:'c3',date:at(3),title:'חשבון חשמל',detail:'לתשלום · דוגמה',kind:'bill'},
{id:'c4',date:at(5),title:'פסטה לערב',detail:'מהתפריט',kind:'meal'},
{id:'c5',date:at(8),title:'חידוש ביטוח',detail:'תזכורת דוגמה',kind:'bill'},
{id:'c6',date:at(10),title:'זמן יחד בחוץ',detail:'רעיון לדייט',kind:'date'}
]}
function todayISO(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Prague',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function localNoon(iso){const [y,m,d]=iso.split('-').map(Number);return new Date(y,m-1,d,12,0,0)}
function localIso(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function startOfWeek(d){const x=new Date(d.getFullYear(),d.getMonth(),d.getDate());x.setDate(x.getDate()-x.getDay());return x}
function shortEvent(e){if(e.kind==='date')return 'דייט';if(e.kind==='shop')return 'קניות';if(e.kind==='bill'){const t=(e.title||'חשבון');return t.includes('חשמל')?'חשמל':t.slice(0,6)}if(e.kind==='meal')return (e.title||'ארוחה').slice(0,6);return (e.title||'אירוע').slice(0,6)}
function formatDayLabel(iso){const d=localNoon(iso);return d.toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'short',timeZone:'Europe/Prague'})}
function eventsOn(iso){ensureMenu();return (data.calendar||[]).filter(e=>e.date===iso)}
function calendarWidget(){ensureMenu();if(!selectedDay)selectedDay=todayISO();const today=todayISO();const wd=['א׳','ב׳','ג׳','ד׳','ה׳','ו׳','ש׳'];
const headers=wd.map(w=>`<span class="calhd">${w}</span>`).join('');
const cell=(d)=>{const iso=localIso(d);const ev=eventsOn(iso);const isToday=iso===today;const labels=ev.slice(0,2).map(e=>`<span class="calevent ${e.kind}">${esc(shortEvent(e))}</span>`).join('')+(ev.length>2?`<span class="calevent more">+${ev.length-2}</span>`:'');const outside=monthView&&d.getMonth()!==localNoon(today).getMonth();return `<button type="button" class="calcell ${isToday?'today':''} ${selectedDay===iso?'selected':''} ${ev.length?'has':''} ${outside?'outside':''}" data-day="${iso}" aria-pressed="${selectedDay===iso}" aria-label="${formatDayLabel(iso)}${ev.length?' · '+ev.map(e=>e.title).join(', '):''}"><span class="calnum">${d.getDate()}</span><span class="calchips">${labels}</span></button>`};
let body='';
if(monthView){
  const base=localNoon(today);const first=new Date(base.getFullYear(),base.getMonth(),1,12);const gridStart=startOfWeek(first);const last=new Date(base.getFullYear(),base.getMonth()+1,0,12);const gridEnd=addDays(startOfWeek(last),6);
  for(let d=new Date(gridStart);d<=gridEnd;d=addDays(d,1)) body+=cell(d);
}else{
  const start=startOfWeek(localNoon(today));
  for(let i=0;i<14;i++) body+=cell(addDays(start,i));
}
return `<div class="calgrid-wrap"><div class="calgrid-head">${headers}</div><div class="calgrid ${monthView?'month':'fortnight'}">${body}</div></div>`}


function shoppingSuggestions(){ensureMenu();const base=['ביצים','אבוקדו','קפה','חלב','לחם','עגבניות'];const ranked=Object.entries(data.freq||{}).sort((a,b)=>b[1]-a[1]).map(([n])=>n);const recent=[...data.shopping].reverse().map(t=>t.name);return [...new Set([...ranked,...recent,...base])].filter(n=>!data.shopping.some(t=>!t.done&&productKey(t.name)===productKey(n))).slice(0,6)}
function bumpFreq(name){ensureMenu();data.freq[name]=(data.freq[name]||0)+1}
function addIngredientNames(names){let count=0;names.forEach(name=>{const existing=data.shopping.find(t=>!t.done&&productKey(t.name)===productKey(name));if(existing){existing.qty=Math.min(99,(existing.qty||1)+1);bumpFreq(existing.name);count++}else{const info=lookupProduct(name);data.shopping.push({id:newId(),name,qty:1,unit:'יח׳',category:info.category,art:info.art,fromMeal:true,shoppingV3:true,done:false});bumpFreq(name);count++}});save();return count}
function bindCasa(){if($('#toggle-month-view'))$('#toggle-month-view').onclick=()=>{monthView=!monthView;render()};document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.day;render()});document.querySelectorAll('[data-edit-meal]').forEach(b=>b.onclick=()=>{editingMealId=b.dataset.editMeal;go('meal-edit')});document.querySelectorAll('[data-plan-meal]').forEach(b=>b.onclick=()=>{ensureMenu();if(!data.plannedMeals.includes(b.dataset.planMeal))data.plannedMeals.push(b.dataset.planMeal);const dish=getMenu().find(m=>m.id===b.dataset.planMeal);const day=selectedDay||todayISO();data.calendar.push({id:'m'+newId(),date:day,title:dish?dish.title:'מנה מהתפריט',detail:'מהתפריט',kind:'meal'});save();toast('נוסף לתכנון השבוע');render()});document.querySelectorAll('[data-add-dish]').forEach(b=>b.onclick=()=>{const dish=getMenu().find(m=>m.id===b.dataset.addDish);if(!dish)return;const n=addIngredientNames(dish.ingredients);go('shopping');toast(n?`${n} רכיבים עודכנו ברשימה`:'הרכיבים כבר ברשימה')});if($('#clear-bought'))$('#clear-bought').onclick=()=>{data.shopping=data.shopping.filter(t=>!t.done);save();boughtExpanded=false;render();toast('הפריטים שנקנו נוקו מהרשימה')};if($('#add-all-ingredients'))$('#add-all-ingredients').onclick=()=>{const m=getMenu().find(m=>m.id===selectedMeal);if(!m)return;const n=addIngredientNames(m.ingredients);go('shopping');toast(n?`${n} רכיבים עודכנו ברשימה`:'הרכיבים כבר ברשימה')};if($('#add-ing-field'))$('#add-ing-field').onclick=()=>{const box=$('#ing-fields');const i=box.querySelectorAll('.ing-input').length;const input=document.createElement('input');input.className='ing-input';input.maxLength=60;input.placeholder='רכיב';input.dataset.ing=String(i);box.append(input);input.focus()};if($('#save-dish'))$('#save-dish').onclick=()=>{const title=$('#dish-title').value.trim();if(!title){toast('צריך שם למנה');return}const ingredients=[...document.querySelectorAll('.ing-input')].map(i=>i.value.trim()).filter(Boolean);if(!ingredients.length){toast('הוסיפו לפחות רכיב אחד');return}ensureMenu();const payload={id:editingMealId||('dish'+newId()),title,category:$('#dish-category').value,time:Math.max(1,Math.min(240,Number($('#dish-time').value)||20)),note:$('#dish-note').value.trim(),instructions:$('#dish-instructions').value.trim(),ingredients,art:'bowl'};const idx=data.menu.findIndex(m=>m.id===payload.id);if(idx>=0)data.menu[idx]=payload;else data.menu.push(payload);editingMealId=null;save();selectedMeal=payload.id;go('meal');toast('המנה נשמרה')};if($('#delete-dish'))$('#delete-dish').onclick=()=>{ensureMenu();data.menu=data.menu.filter(m=>m.id!==editingMealId);data.plannedMeals=(data.plannedMeals||[]).filter(id=>id!==editingMealId);editingMealId=null;save();go('meals');toast('המנה נמחקה מהתפריט המקומי')}}
