function dataUrlBytes(u){const i=u.indexOf(',');return i<0?0:Math.floor((u.length-i-1)*3/4)}
function hasPhoto(p){return !!(window.CASA_CLOUD&&CASA_CLOUD.hasPhoto?CASA_CLOUD.hasPhoto(p):(typeof p==='string'&&p.length>8))}
function photoTag(photo,cls,alt){if(window.CASA_CLOUD&&CASA_CLOUD.photoTag){const t=CASA_CLOUD.photoTag(photo,cls,alt);if(t)return t}if(typeof photo==='string'&&(photo.startsWith('data:')||photo.startsWith('blob:')||photo.startsWith('http')))return `<img class="${cls||''}" src="${photo}" alt="${esc(alt||'')}" loading="lazy">`;return ''}
async function storePhoto(dataUrl){
  if(window.CASA_CLOUD&&CASA_CLOUD.active&&CASA_CLOUD.uploadPhoto&&typeof dataUrl==='string'&&dataUrl.startsWith('data:')){
    try{return await CASA_CLOUD.uploadPhoto(dataUrl)}
    catch(e){console.warn(e);toast('לא הצלחנו לשמור את התמונה בשרת. היא נשמרה במכשיר הזה לעת עתה.')}
  }
  return dataUrl;
}
function dropPhoto(p){if(window.CASA_CLOUD&&CASA_CLOUD.removePhoto)CASA_CLOUD.removePhoto(p).catch(()=>{})}
function paintHigh(ctx,src,dw,dh){ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(src,0,0,dw,dh)}
function downscaleCanvas(src,tw,th){
  let sw=src.width||src.naturalWidth,sh=src.height||src.naturalHeight,cur=src,made=[];
  while(Math.max(sw,sh)>Math.max(tw,th)*2){
    const nw=Math.max(tw,Math.round(sw/2)),nh=Math.max(th,Math.round(sh/2));
    const c=document.createElement('canvas');c.width=nw;c.height=nh;paintHigh(c.getContext('2d'),cur,nw,nh);
    made.push(c);cur=c;sw=nw;sh=nh;
  }
  const out=document.createElement('canvas');out.width=tw;out.height=th;const ctx=out.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,tw,th);paintHigh(ctx,cur,tw,th);
  return out}
async function compressImage(file,max=1000,q=.85,limit=0){
  if(!file)throw new Error('nofile');if(file.type&&!/^image\//.test(file.type))throw new Error('type');
  let src,url;try{src=await createImageBitmap(file,{imageOrientation:'from-image'})}catch{url=URL.createObjectURL(file);src=await new Promise((res,rej)=>{const i=new Image();i.onload=()=>res(i);i.onerror=rej;i.src=url})}
  const w=src.width||src.naturalWidth,h=src.height||src.naturalHeight;
  const encode=(cw,ch,qq)=>downscaleCanvas(src,cw,ch).toDataURL('image/jpeg',qq);
  let scale=Math.min(1,max/Math.max(w,h)),cw=Math.max(1,Math.round(w*scale)),ch=Math.max(1,Math.round(h*scale)),qq=q,out=encode(cw,ch,qq);
  if(limit){while(dataUrlBytes(out)>limit&&qq>0.8){qq=Math.max(0.8,Math.round((qq-0.04)*100)/100);out=encode(cw,ch,qq)}while(dataUrlBytes(out)>limit&&Math.max(cw,ch)>900){cw=Math.max(1,Math.round(cw*0.9));ch=Math.max(1,Math.round(ch*0.9));out=encode(cw,ch,qq)}}
  try{src.close?.()}catch{}if(url)URL.revokeObjectURL(url);return out}
function pickImage(){return new Promise(res=>{const i=document.createElement('input');i.type='file';i.accept='image/*';i.hidden=true;i.id='v7-file';document.body.append(i);let done=false;const fin=f=>{if(done)return;done=true;i.remove();res(f)};i.onchange=()=>fin(i.files&&i.files[0]||null);i.addEventListener('cancel',()=>fin(null));i.click()})}
async function choosePhoto(opts={}){const f=await pickImage();if(!f)return null;try{return await compressImage(f,opts.max??600,opts.q??.72,opts.limit??0)}catch(e){console.warn('CASA photo',e);toast('לא הצלחנו לקרוא את התמונה. נסו תמונה אחרת.');return null}}
function avoDeco(kind='tiny'){const art='<svg class="avo" viewBox="0 0 64 80" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g transform="rotate(-14 32 40)"><path d="M32 4C16 6 10 24 12 46c2 20 10 30 20 30s18-10 20-30C54 24 48 6 32 4Z" fill="#2F4A1E"/><path d="M32 12C19 14 15 28 17 46c2 16 8 24 15 24s13-8 15-24C49 28 45 14 32 12Z" fill="#F6EEB8"/><circle cx="32" cy="48" r="11" fill="#8B5A2B"/><ellipse cx="28.5" cy="44.5" rx="3.2" ry="4.4" fill="#C69660" opacity=".85"/><path d="M44 8c9 2 13 9 11 16-8-3-13-9-11-16Z" fill="#86AF37"/></g></svg>';return `<span class="avo-${kind}" aria-hidden="true">${art}</span>`}

/* ---------- sheet (bottom dialog, outside #app so renders don't kill it) ---------- */
function openSheet(html,label){closeSheet();const s=document.createElement('div');s.id='v7-sheet';s.className='v7-sheet';s.innerHTML=`<div class="v7-sheet-inner" role="dialog" aria-modal="true" aria-label="${esc(label||'')}"><div class="photo-sheet-handle" aria-hidden="true"></div>${html}</div>`;s.onclick=e=>{if(e.target===s)closeSheet()};document.body.append(s);document.body.classList.add('sheet-open');vvUpdate();return s}
function closeSheet(){$('#v7-sheet')?.remove();document.body.classList.remove('sheet-open')}
function closePhotoView(){$('#casa-photoview')?.remove()}
function openPhotoView(photo,title,onReplace){closePhotoView();const url=(window.CASA_CLOUD&&CASA_CLOUD.peekPhotoUrl&&CASA_CLOUD.peekPhotoUrl(photo))||(typeof photo==='string'&&(photo.startsWith('data:')||photo.startsWith('http')||photo.startsWith('blob:'))?photo:'');const path=(window.CASA_CLOUD&&CASA_CLOUD.photoPath&&CASA_CLOUD.photoPath(photo))||'';const media=url?`<img src="${url}" alt="${esc(title||'')}">`:`<span class="photowait photoview-wait"${path?` data-photo-path="${esc(path)}"`:''} role="img" aria-label="${esc(title||'תמונה')}"></span>`;const s=document.createElement('div');s.id='casa-photoview';s.className='photoview';s.innerHTML=`<div class="photoview-inner" role="dialog" aria-modal="true" aria-label="${esc(title||'תמונה')}">${media}${title?`<p class="photoview-cap">${esc(title)}</p>`:''}<div class="photoview-actions">${onReplace?`<button type="button" class="secondary" id="pv-replace">החלפת תמונה</button>`:''}<button type="button" class="quiet" id="pv-close">סגירה</button></div></div>`;s.addEventListener('click',e=>{if(e.target===s)closePhotoView()});document.body.append(s);s.querySelector('#pv-close').onclick=closePhotoView;const r=s.querySelector('#pv-replace');if(r)r.onclick=()=>{closePhotoView();onReplace&&onReplace()};if(!url&&window.CASA_CLOUD&&CASA_CLOUD.bindPhotos)CASA_CLOUD.bindPhotos()}
function confirmSheet(text,yes,onYes){const s=openSheet(`<h3>${esc(text)}</h3><div class="sheet-actions"><button class="primary dangerbtn" id="cf-yes">${esc(yes)}</button><button class="secondary" id="cf-no">ביטול</button></div>`,text);s.querySelector('#cf-no').onclick=closeSheet;s.querySelector('#cf-yes').onclick=()=>{closeSheet();onYes()}}

/* ---------- keyboard / visual viewport ---------- */
function typingFocus(){const ae=document.activeElement;if(!ae)return false;const t=ae.tagName;if(t!=='INPUT'&&t!=='TEXTAREA'&&t!=='SELECT')return false;const typ=ae.type||'';return !ae.readOnly&&!ae.disabled&&!/^(button|checkbox|radio|file|submit|reset|hidden|range|color)$/.test(typ)}
function pinNav(){const n=document.querySelector('.nav');if(!n)return;n.style.position='absolute';n.style.left='0';n.style.right='0';n.style.bottom='0';n.style.top='auto';n.style.transform='none';n.style.margin='0';n.style.width='100%'}
function scrollRoot(){return document.querySelector('#app > main')||document.scrollingElement||document.documentElement}
function syncAppFrame(){
  const root=document.documentElement;
  const vv=window.visualViewport;
  const inner=window.innerHeight||0;
  const vis=vv?Math.round(vv.height+vv.offsetTop):0;
  const client=root.clientHeight||0;
  let h=Math.max(inner,vis,client);
  try{
    const stand=window.navigator.standalone===true||window.matchMedia('(display-mode: standalone)').matches;
    if(stand&&window.screen){
      const sh=Math.max(screen.height||0,screen.availHeight||0);
      if(sh>h+24&&sh-h<=180)h=sh;
    }
  }catch{}
  if(h>0)root.style.setProperty('--app-h',h+'px');
}
function resetScroll(){const sc=scrollRoot();if(sc){sc.scrollTop=0;sc.scrollLeft=0}window.scrollTo(0,0);document.documentElement.scrollTop=0;document.body.scrollTop=0;if(!typingFocus()){document.body.classList.remove('kb-open');document.documentElement.style.setProperty('--kb','0px')}syncAppFrame();pinNav()}
function vvUpdate(){syncAppFrame();const vv=window.visualViewport;const typing=typingFocus();const covered=vv?Math.max(0,Math.round((window.innerHeight||0)-vv.height-vv.offsetTop)):0;const open=typing&&covered>120;const r=document.documentElement.style;r.setProperty('--kb',(open?covered:0)+'px');if(vv)r.setProperty('--vvh',Math.round(vv.height)+'px');document.body.classList.toggle('kb-open',open);if(!open)pinNav()}
if(window.visualViewport){visualViewport.addEventListener('resize',vvUpdate);visualViewport.addEventListener('scroll',vvUpdate)}
window.addEventListener('resize',syncAppFrame);
window.addEventListener('orientationchange',()=>setTimeout(syncAppFrame,50));
document.addEventListener('focusin',vvUpdate);document.addEventListener('focusout',()=>setTimeout(vvUpdate,0));
syncAppFrame();
function keepVisible(el){if(!el)return;const run=()=>{const sc=scrollRoot();const vv=window.visualViewport;const r=el.getBoundingClientRect();const top=vv?vv.offsetTop:0;const bottom=vv?vv.height+vv.offsetTop:window.innerHeight;const dy=r.bottom>bottom-12?(r.bottom-bottom+16):r.top<top+8?(r.top-top-16):0;if(!dy)return;if(sc)sc.scrollTop+=dy;else window.scrollBy(0,dy)};setTimeout(run,60);setTimeout(run,380)}

/* ---------- supermarket session ---------- */
function superSession(){try{return JSON.parse(localStorage.getItem(SUPER_KEY)||'null')}catch{return null}}
function startSuper(){if(!superSession())try{localStorage.setItem(SUPER_KEY,JSON.stringify({startedAt:Date.now()}))}catch{}go('supermarket')}
function endSuper(clear){try{localStorage.removeItem(SUPER_KEY)}catch{}releaseWake();if(clear){const gone=data.shopping.filter(t=>t.done);data.shopping=data.shopping.filter(t=>!t.done);save();gone.forEach(t=>{if(t.photo)dropPhoto(t.photo)})}else if(data.shopping.some(t=>t.done)){data.shopping.forEach(t=>{t.done=false});save()}closeSheet();go('shopping');toast(clear?'הקנייה הסתיימה · מה שסומן ירד מהרשימה':'הקנייה הסתיימה')}
function superMinutes(){const s=superSession();return s?Math.max(0,Math.floor((Date.now()-s.startedAt)/60000)):0}
function superElapsedLabel(){const m=superMinutes();return m<1?'עכשיו':m<60?`${m} דק׳`:`${Math.floor(m/60)}:${String(m%60).padStart(2,'0')} ש׳`}
function superBar(){const s=superSession();if(!s||page==='supermarket')return '';const left=data.shopping.filter(t=>!t.done).length;return `<button class="superbar" id="superbar" type="button" data-go="supermarket" aria-label="חזרה למצב אני בסופר · נשארו ${left} פריטים"><span class="superbar-ic">${svg('shop')}</span><span class="superbar-text"><strong>אני בסופר</strong><small>${left?`נשארו ${left} פריטים`:'הכול סומן'}</small></span><span class="superbar-time" id="superbar-time">${superElapsedLabel()}</span>${svg('chev','superbar-chev')}</button>`}
async function holdWake(){try{if('wakeLock' in navigator&&!wakeLock&&document.visibilityState==='visible'){wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null})}}catch{}}
function releaseWake(){try{wakeLock?.release()}catch{}wakeLock=null}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&page==='supermarket')holdWake()});
setInterval(()=>{const t=document.getElementById('superbar-time');if(t)t.textContent=superElapsedLabel()},30000);
function itemThumb(t,big){const pic=t.photo?photoTag(t.photo,'li-photo',t.name||''):'';return pic||`<span class="li-art">${productArt(t.art)}</span>`}
function superRow(t){return `<button type="button" class="super-row ${t.done?'done':''}" data-super="${t.id}" aria-pressed="${t.done}" aria-label="${t.done?'ביטול סימון: ':'סימון: '}${esc(t.name)}"><span class="super-check" aria-hidden="true">${t.done?svg('check'):''}</span>${itemThumb(t,true)}<span class="super-name">${esc(t.name)}</span><span class="super-qty">${t.qty>1||t.unit!=='יח׳'?`${t.qty} ${esc(t.unit)}`:''}</span></button>`}
function supermarket(){if(!superSession())try{localStorage.setItem(SUPER_KEY,JSON.stringify({startedAt:Date.now()}))}catch{}
  const open=data.shopping.filter(t=>!t.done),marked=data.shopping.filter(t=>t.done),total=data.shopping.length,pct=total?Math.round(marked.length/total*100):0;
  return `<div class="supermode"><div class="super-top">${shopSwitch('super')}<button type="button" class="super-end" id="super-end">סיום</button></div>
<div class="super-progress"><div class="super-progress-row"><strong>${open.length?`נשארו ${open.length}`:'הכול סומן!'}</strong><span>${marked.length?`${marked.length} מתוך ${total} סומנו`:`${total} ברשימה`} · ${superElapsedLabel()}</span></div><div class="progressbar" role="progressbar" aria-label="התקדמות הקנייה" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><span style="width:${pct}%"></span></div></div>
${!total?`<p class="super-done">${avoDeco('done')}<span>הרשימה ריקה.</span></p>`:!open.length?`<p class="super-done">${avoDeco('done')}<span>סימנתם הכול. אפשר ללחוץ "סיום".</span></p>`:''}
<div class="super-list notebook">${data.shopping.map(superRow).join('')}</div>
<p class="super-hint">נוגעים בפריט כדי לסמן אותו בקו. הוא נשאר במקום. אפשר לצאת מהמסך — הקנייה ממשיכה בפס למטה.</p></div>`}

/* ---------- home ---------- */
function quick(){return `<div class="quick"><input id="quick-item" aria-label="הוסף לעגלה" placeholder="הוסף לעגלה" maxlength="90" autocomplete="off" enterkeyhint="done"><button id="add-item" aria-label="הוספה לעגלה">+</button></div>`}
function dishVisual(m,cls=''){if(!m)return '';const pic=m.photo?photoTag(m.photo,`dishphoto ${cls}`,m.title||''):'';return pic||`<div class="dishph ${cls}" role="img" aria-label="עדיין אין תמונה למנה">${svg('cutlery')}<span>עדיין אין תמונה</span></div>`}
function eventDetail(e){return [e.time||'',e.detail||e.note||''].filter(Boolean).join(' · ')}
function home(){const menu=getMenu();const dinner=menu.find(m=>m.category==='dinner'&&m.photo)||menu.find(m=>m.photo)||menu.find(m=>m.category==='dinner')||menu[0];const items=eventsOn(selectedDay).slice().sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));const openCount=data.shopping.filter(t=>!t.done).length;
return `<div class="homedate-mini"><time datetime="${todayISO()}">${formatDayLabel(todayISO())}</time></div><div class="grid homegrid"><div class="stack"><section class="card calendarcard has-avo">${avoDeco('mark')}<div class="cardhead"><h2 class="withicon">${avoDeco('tiny')}היומן של הבית</h2><div class="cardhead-actions"><button type="button" class="quiet" id="toggle-month-view" aria-pressed="${monthView}">${monthView?'שבועיים':'חודש מלא'}</button><button type="button" class="roundadd" id="add-event" aria-label="הוספת אירוע ליומן">${svg('plus')}</button></div></div>${calendarWidget()}<div class="daypanel">${items.length?items.map(e=>`<div class="dayitem"><span class="dot ${e.kind}"></span><div><strong>${esc(e.title)}</strong><small>${esc(eventDetail(e))}</small></div><button type="button" class="dayitem-del" data-del-event="${esc(e.id)}" aria-label="מחיקת ${esc(e.title)}">${svg('close')}</button></div>`).join(''):`<div class="dayempty">${avoDeco('tiny')}<p>אין אירועים ביום הזה.</p></div>`}</div></section>${CASA_CLOUD.active?CASA_CLOUD.upcomingCard():`<section class="card upcomingcard"><div class="cardhead"><h2 class="withicon">${avoDeco('tiny')}לקראת השבוע</h2></div><div class="upcoming"><div class="dateblock">יום<strong>ו׳</strong></div><div><h3>ערב קטן בבית</h3><p class="sub">בבית או בחוץ — עוד נבחר</p></div></div></section>`}</div><div class="stack"><section class="card mealcard compact"><div class="cardhead"><h2 class="withicon">${svg('cutlery')}תפריט</h2><button class="quiet" data-go="meals">לכל התפריט</button></div>${dinner?`<button type="button" class="mealrow" data-meal="${dinner.id}" aria-label="פרטי ${esc(dinner.title)}"><span class="mealrow-thumb">${dishVisual(dinner)}</span><span class="mealrow-text"><strong>${esc(dinner.title)}</strong><small>${catLabel(dinner.category)} · ${dinner.time} דקות</small></span></button>`:`<div class="dayempty">${avoDeco('tiny')}<p>עדיין אין מנות בתפריט.</p></div>`}</section><section class="card quickcard compact"><div class="cardhead"><h2 class="withicon">${svg('shop')}עגלת סופר</h2><button class="quiet" data-go="shopping">לרשימה</button></div>${quick()}<div class="sub">${openCount?openCount+' פריטים ברשימה':'הרשימה ריקה — אפשר להוסיף כאן.'}</div></section></div></div>`}
function openEventSheet(date){const s=openSheet(`<h3>${svg('cal')} אירוע חדש ביומן</h3><label>מה קורה?<input id="ev-title" maxlength="80" placeholder="למשל ארוחה אצל ההורים" autocomplete="off" enterkeyhint="next"></label><div class="formrow"><label>תאריך<input id="ev-date" type="date" value="${date||todayISO()}"></label><label>שעה<input id="ev-time" type="time"></label></div><label><span>הערה <span class="opt">(לא חובה)</span></span><input id="ev-note" maxlength="120" placeholder="מקום, מה להביא…" autocomplete="off" enterkeyhint="done"></label><p class="formerror" id="ev-error" role="alert"></p><div class="sheet-actions"><button class="primary" id="ev-save">שמירה ביומן</button><button class="secondary" id="ev-cancel">ביטול</button></div><p class="sub sheetnote">${T('נשמר ביומן המשותף ומסונכרן לכל בני הבית.','נשמר במכשיר הזה (הדגמה).')}</p>`,'אירוע חדש ביומן');
  const saveEv=()=>{const title=$('#ev-title').value.trim(),date=$('#ev-date').value,time=$('#ev-time').value,note=$('#ev-note').value.trim();if(!title){$('#ev-error').textContent='מה האירוע? כתבו כותרת קצרה.';$('#ev-title').focus();return}if(!/^\d{4}-\d{2}-\d{2}$/.test(date)){$('#ev-error').textContent='בחרו תאריך.';return}
    ensureMenu();data.calendar.push({id:'e'+newId(),date,time:time||'',title:title.slice(0,80),detail:note.slice(0,120),kind:'event'});selectedDay=date;save();closeSheet();render();toast('האירוע נוסף ליומן')};
  s.querySelector('#ev-save').onclick=saveEv;s.querySelector('#ev-cancel').onclick=closeSheet;s.querySelector('#ev-note').onkeydown=e=>{if(e.key==='Enter')saveEv()};s.querySelector('#ev-title').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#ev-time').focus()}};setTimeout(()=>s.querySelector('#ev-title')?.focus(),60)}

/* ---------- shopping ---------- */
function shopRows(items){return items.map(t=>`<div class="li ${editingCategory===t.id?'open':''}" data-product="${t.id}"><button type="button" class="li-ico" data-item-photo="${t.id}" aria-label="${t.photo?'צפייה בתמונה':'הוספת תמונה'} · ${esc(t.name)}">${t.photo?photoTag(t.photo,'li-photo-mini',t.name||''):svg('camera')}</button><button type="button" class="li-main" data-edit-category="${t.id}" aria-label="${esc(t.name)} · עריכה"><span class="productname">${esc(t.name)}</span>${t.qty>1||t.unit!=='יח׳'?`<span class="li-qty">${t.qty} ${esc(t.unit)}</span>`:''}${t.fromMeal?'<span class="li-tag">מהתפריט</span>':''}</button><button class="li-more" data-edit-category="${t.id}" aria-label="עוד אפשרויות · ${esc(t.name)}" aria-expanded="${editingCategory===t.id}"><svg viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><circle cx="10" cy="4.5" r="1.5"/><circle cx="10" cy="10" r="1.5"/><circle cx="10" cy="15.5" r="1.5"/></svg></button>${editingCategory===t.id?`<div class="li-editor"><div class="quantity mini" aria-label="כמות ${esc(t.name)}"><button data-qty="${t.id}" data-step="-1" aria-label="הפחתת כמות ${esc(t.name)}" ${t.qty<=1?'disabled':''}>−</button><output>${t.qty}</output><button data-qty="${t.id}" data-step="1" aria-label="הגדלת כמות ${esc(t.name)}" ${t.qty>=99?'disabled':''}>+</button></div><select data-item-unit="${t.id}" aria-label="יחידה ${esc(t.name)}">${['יח׳','חבילות','בקבוקים','ק״ג'].map(u=>`<option ${t.unit===u?'selected':''}>${u}</option>`).join('')}</select><select data-item-category="${t.id}" aria-label="קטגוריה ${esc(t.name)}">${allShoppingCategories().map(c=>`<option ${t.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select>${t.photo?`<button type="button" class="quiet" data-remove-photo="${t.id}">הסרת תמונה</button>`:''}<button type="button" class="quiet dangerish" data-del-item="${t.id}">מחיקה</button></div>`:''}</div>`).join('')}
function shopSwitch(on){return `<div class="segswitch" role="group" aria-label="מצב"><button type="button" class="${on==='list'?'on':''}" ${on==='list'?'aria-pressed="true"':'data-go="shopping" aria-pressed="false"'}>רשימה</button><button type="button" class="${on==='super'?'on':''}" ${on==='super'?'aria-pressed="true"':'id="start-super" aria-pressed="false"'}>אני בסופר</button></div>`}
function shopping(){if(!superSession()&&data.shopping.some(t=>t.done)){data.shopping.forEach(t=>{t.done=false});save()}
const items=data.shopping;const last=lastAddedId&&data.shopping.find(t=>t.id===lastAddedId);
return `<div class="pagehead shophead"><div><h1 class="withicon">${avoDeco('tiny')}רשימת קניות</h1><span class="pagehead-sub">${items.length?`${items.length} ברשימה`:''}</span></div>${shopSwitch('list')}</div>
<div class="addbar" id="addbar"><div class="quick"><button type="button" class="addbar-photo ${pendingPhoto?'has':''}" id="add-photo" aria-label="${pendingPhoto?'החלפת התמונה שתצורף':'הוסף תמונה'}">${pendingPhoto?`<img src="${pendingPhoto}" alt="">`:svg('camera')}</button><input id="quick-item" aria-label="מה להוסיף לרשימה?" placeholder="מה להוסיף?" maxlength="90" autocomplete="off" enterkeyhint="done"><button id="add-item" aria-label="הוספה לרשימה">+</button></div><p id="add-error" role="alert"></p><p id="classification-hint" class="sub"></p></div>
${last?`<div class="justadded" role="status">נוסף: <strong>${esc(last.name)}</strong>${last.photo?`<img src="${last.photo}" alt="">`:`<button type="button" id="justadded-photo">${svg('camera')} תמונה</button>`}<button type="button" class="justadded-x" id="justadded-close" aria-label="סגירה">${svg('close')}</button></div>`:''}
<section class="listpanel notebook has-avo">${avoDeco('mark')}${items.length?shopRows(items):`<p class="listempty">${avoDeco('empty')}הרשימה ריקה.</p>`}</section>`}
function addItem(){const input=$('#quick-item'),name=input.value.trim().replace(/\s+/g,' ');const error=$('#add-error');const fail=msg=>{if(error)error.textContent=msg;else toast(msg)};if(!name){fail('מה נוסיף? כתבו שם מוצר.');input.focus();return}const value=$('#add-qty')?.value??'1';const qty=Number(value);if(!value.trim()||!Number.isInteger(qty)||qty<1||qty>99){fail('בחרו כמות שלמה בין 1 ל־99.');return}const unit=$('#add-unit')?.value||'יח׳';const existing=data.shopping.find(t=>!t.done&&productKey(t.name)===productKey(name)&&t.unit===unit);if(existing&&existing.qty+qty>99){fail('הכמות הכוללת גדולה מ־99. אפשר לעדכן את הכמות ברשימה.');return}let item;if(existing){existing.qty+=qty;item=existing}else{const info=lookupProduct(name);item={id:newId(),name,qty,unit,category:info.category,art:info.art,shoppingV3:true,done:false};data.shopping.push(item)}if(pendingPhoto&&page==='shopping'){item.photo=pendingPhoto;pendingPhoto=null}lastAddedId=item.id;shopFilter='all';bumpFreq(existing?existing.name:name);if(!save()&&item.photo){delete item.photo;save()}render();const again=$('#quick-item');if(again){again.focus({preventScroll:true});keepVisible($('#addbar')||again)}toast(existing?'הפריט כבר ברשימה — הכמות עודכנה':'נוסף לרשימה')}
async function attachItemPhoto(id){const url=await choosePhoto({max:1000,q:.85,limit:350*1024});if(!url)return;const t=data.shopping.find(x=>x.id===id);if(!t)return;const old=t.photo;t.photo=await storePhoto(url);if(!save()){if(old)t.photo=old;else delete t.photo;return}if(old&&old!==t.photo)dropPhoto(old);render();toast('התמונה נוספה')}
function bindShopping(){document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const t=data.shopping.find(t=>t.id===+b.dataset.qty);t.qty=Math.max(1,Math.min(99,t.qty+Number(b.dataset.step)));save();render()});document.querySelectorAll('[data-edit-category]').forEach(b=>b.onclick=()=>{editingCategory=editingCategory===+b.dataset.editCategory?null:+b.dataset.editCategory;render()});document.querySelectorAll('[data-item-category]').forEach(s=>s.onchange=()=>{const t=data.shopping.find(t=>t.id===+s.dataset.itemCategory);t.category=s.value;editingCategory=null;shopFilter='all';save();render()});document.querySelectorAll('[data-item-unit]').forEach(x=>x.onchange=()=>{const t=data.shopping.find(t=>t.id===+x.dataset.itemUnit);t.unit=x.value;save();render()});document.querySelectorAll('[data-shop-filter]').forEach(b=>b.onclick=()=>{shopFilter=b.dataset.shopFilter;render()});if($('#toggle-bought'))$('#toggle-bought').onclick=()=>{boughtExpanded=!boughtExpanded;render()};document.querySelectorAll('[data-common]').forEach(b=>b.onclick=()=>{$('#quick-item').value=b.dataset.common;addItem()});if($('#classification-hint'))$('#quick-item').addEventListener('input',()=>{const v=$('#quick-item').value.trim();$('#add-error').textContent='';const info=lookupProduct(v);$('#classification-hint').textContent=!v?'':info.category==='כללי'?'יתווסף ל״כללי״ · אפשר לשנות קטגוריה':`קטגוריה: ${info.category}`})}

/* ---------- menu ---------- */
function catLabel(id){return (menuCategories.find(c=>c.id===id)||{label:''}).label}
function menuSorted(cat){return getMenu().map((m,i)=>[m,i]).filter(([m])=>m.category===cat).sort((a,b)=>((a[0].order??a[1])-(b[0].order??b[1]))||a[1]-b[1]).map(x=>x[0])}
function normalizeOrder(cat){menuSorted(cat).forEach((m,i)=>{if(m.order!==i)m.order=i})}
function meals(){ensureMenu();
const short={breakfast:'בוקר',lunch:'צהריים',dinner:'ערב',snack:'ביניים'};
const sections=menuOrder.map(id=>({id,label:short[id]||catLabel(id),items:menuSorted(id)}));
const visible=menuEdit?sections:sections.filter(s=>s.items.length);
const line=(m,i,list)=>{
  if(menuEdit)return `<div class="editrow" data-dish-row="${m.id}"><span class="editrow-thumb">${dishVisual(m,'mini')}</span><button type="button" class="editrow-name" data-edit-meal="${m.id}" aria-label="עריכת פרטי ${esc(m.title)}">${esc(m.title)}</button><div class="editrow-move"><button type="button" data-move="${m.id}" data-dir="-1" aria-label="הזזה למעלה: ${esc(m.title)}" ${i===0?'disabled':''}>${svg('up')}</button><button type="button" data-move="${m.id}" data-dir="1" aria-label="הזזה למטה: ${esc(m.title)}" ${i===list.length-1?'disabled':''}>${svg('down')}</button></div><select data-move-cat="${m.id}" aria-label="העברה לארוחה אחרת: ${esc(m.title)}">${menuCategories.map(c=>`<option value="${c.id}" ${c.id===m.category?'selected':''}>${short[c.id]}</option>`).join('')}</select><button type="button" class="editrow-del" data-del-dish="${m.id}" aria-label="מחיקת ${esc(m.title)}">${svg('trash')}</button></div>`;
  const note=(m.note||'').trim();
  return `<button type="button" class="menuline" data-meal="${m.id}" aria-label="${esc(m.title)}">${m.photo?`<span class="menuline-thumb">${dishVisual(m,'mini')}</span>`:''}<span class="menuline-body"><span class="menuline-row"><span class="menuline-name">${esc(m.title)}</span><span class="menuline-lead" aria-hidden="true"></span><span class="menuline-meta">${m.time?`${m.time} דק׳`:''}</span></span>${note?`<span class="menuline-note">${esc(note)}</span>`:''}</span></button>`;
};
const book=visible.length?visible.map(s=>`<section class="menusection" aria-label="${s.label}"><h2 class="menusection-h"><span>${esc(s.label)}</span></h2>${s.items.length?s.items.map((m,i)=>line(m,i,s.items)).join(''):`<p class="menu-empty">${avoDeco('tiny')}אין מנות בארוחה הזו.</p>`}</section>`).join(''):`<p class="listempty">${avoDeco('empty')}עדיין אין מנות בתפריט.</p>`;
return `<div class="pagehead menuhead"><h1 class="withicon">${avoDeco('tiny')}${svg('cutlery')}תפריט</h1><div class="menuhead-actions"><button type="button" class="pillbtn ${menuEdit?'on':''}" id="menu-edit-toggle" aria-pressed="${menuEdit}">${menuEdit?'סיום':'עריכה'}</button><button type="button" class="pillbtn solid" id="menu-add" aria-label="הוספת מנה">${svg('plus')}מנה</button></div></div>
<div class="menubook ${menuEdit?'is-edit':''} has-avo">${avoDeco('mark')}${book}</div>`}


function meal(){const m=getMenu().find(m=>m.id===selectedMeal)||getMenu()[0];if(!m)return meals();const ings=(m.ingredients||[]).filter(Boolean);return `<button class="back" data-go="meals">→ בחזרה לתפריט</button>${head(esc(m.title),`${catLabel(m.category)} · ${m.time} דקות`)}<div class="grid"><section class="card meal-detail"><div class="dishhero">${dishVisual(m)}</div>${m.note||m.instructions?`<h2>בקצרה</h2><p style="margin-top:10px">${esc(m.instructions||m.note||'')}</p>`:''}${ings.length?`<h3 style="margin-top:18px">רכיבים</h3><ul class="inglist">${ings.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:''}<div class="rowbuttons" style="margin-top:16px"><button class="secondary" data-edit-meal="${m.id}">עריכת המנה</button><button class="secondary" data-plan-meal="${m.id}">לתכנון ביומן</button></div></section>${ings.length?`<section class="card"><h2>מה חסר לנו?</h2><p style="margin-top:8px">בחרו רק מה שצריך לקנות.</p>${ings.map(n=>`<label class="task"><input type="checkbox" name="ingredient" value="${esc(n)}" style="width:21px;height:21px;accent-color:var(--green)"><span>${esc(n)}</span></label>`).join('')}<button class="primary" id="ingredients" style="margin-top:20px">הוספת הנבחרים לקניות</button><button class="secondary" id="add-all-ingredients" style="margin-top:10px">הוספת כל הרכיבים</button><div class="footnote">פריטים שכבר ברשימה הפתוחה ימוזגו לכמות במקום כפילות.</div></section>`:''}</div>`}
function photoPickInner(){const pic=dishDraftPhoto?photoTag(dishDraftPhoto,'','תמונת המנה'):'';return pic?`${pic}<span class="photopick-change">${svg('camera')} החלפת תמונה</span>`:`${svg('camera')}<strong>צילום או בחירת תמונה</strong><small>חובה · תמונה אמיתית של המנה</small>`}
function mealEdit(){ensureMenu();const existing=editingMealId?getMenu().find(m=>m.id===editingMealId):null;const draft=existing||{title:'',category:menuCategory||'dinner',time:20,note:'',instructions:'',ingredients:['']};return `<button class="back" data-go="meals">→ בחזרה לתפריט</button>${head(existing?'עריכת מנה':'מנה חדשה',T('נשמר בתפריט המשותף','נשמר רק בדפדפן · תפריט הבית'))}<section class="card meal-edit-card"><button type="button" class="photopick ${dishDraftPhoto?'has':''}" id="dish-photo-pick" aria-label="${dishDraftPhoto?'החלפת תמונת המנה':'צילום או בחירת תמונה למנה'}">${photoPickInner()}</button><p class="formerror" id="dish-photo-error" role="alert"></p><label>שם המנה<input id="dish-title" maxlength="80" value="${esc(draft.title)}" placeholder="למשל פסטה ביתית" autocomplete="off"></label><div class="formrow"><label>ארוחה<select id="dish-category">${menuCategories.map(c=>`<option value="${c.id}" ${draft.category===c.id?'selected':''}>${c.label}</option>`).join('')}</select></label><label>זמן הכנה (דק׳)<input id="dish-time" type="number" inputmode="numeric" min="1" max="240" value="${draft.time||20}"></label></div><label><span>תיאור קצר <span class="opt">(לא חובה)</span></span><textarea id="dish-note" maxlength="160" rows="2">${esc(draft.note||'')}</textarea></label><label><span>הוראות קצרות <span class="opt">(לא חובה)</span></span><textarea id="dish-instructions" maxlength="400" rows="3">${esc(draft.instructions||'')}</textarea></label><div class="cardhead"><h3>רכיבים <span class="opt">(לא חובה)</span></h3><button class="quiet" id="add-ing-field">+ רכיב</button></div><div id="ing-fields">${(draft.ingredients&&draft.ingredients.length?draft.ingredients:['']).map((n,i)=>`<input class="ing-input" data-ing="${i}" maxlength="60" value="${esc(n)}" placeholder="רכיב">`).join('')}</div><button class="primary" id="save-dish" style="margin-top:18px">${existing?'שמירת שינויים':'הוספה לתפריט'}</button>${existing?`<button class="secondary" id="delete-dish" style="margin-top:10px">מחיקת המנה</button>`:''}</section>`}
function moveDish(id,dir){const m=getMenu().find(x=>x.id===id);if(!m)return;normalizeOrder(m.category);const list=menuSorted(m.category);const i=list.indexOf(m),j=i+dir;if(j<0||j>=list.length)return;const other=list[j];const a=m.order;m.order=other.order;other.order=a;save();render()}
function moveDishToCategory(id,cat){const m=getMenu().find(x=>x.id===id);if(!m||m.category===cat)return;const from=m.category;normalizeOrder(cat);m.order=menuSorted(cat).length;m.category=cat;normalizeOrder(from);save();render();toast(`הועבר ל${catLabel(cat)}`)}
function deleteDish(id){ensureMenu();const gone=data.menu.find(m=>m.id===id);data.menu=data.menu.filter(m=>m.id!==id);data.plannedMeals=(data.plannedMeals||[]).filter(x=>x!==id);save();if(gone?.photo)dropPhoto(gone.photo)}

/* ---------- expenses ---------- */
function expenses(){ensureExpenses();if(expenseView==='analysis')return expensesAnalysis();
const months=expenseMonths();if(!months.includes(expenseMonth))expenseMonth=months[0];
const list=expensesInMonth(expenseMonth);const total=list.reduce((s,e)=>s+e.amount,0);const mi=months.indexOf(expenseMonth);
const byCat={};list.forEach(e=>{byCat[e.category]=(byCat[e.category]||0)+e.amount});const cats=Object.entries(byCat).sort((a,b)=>b[1]-a[1]);const top=cats.slice(0,4),maxC=cats[0]?.[1]||1;
const days=[];list.forEach(e=>{let d=days.find(x=>x.date===e.date);if(!d){d={date:e.date,items:[],sum:0};days.push(d)}d.items.push(e);d.sum+=e.amount});
return `<div class="pagehead"><h1 class="withicon">${avoDeco('tiny')}הוצאות</h1><button type="button" class="exp-review" id="exp-analysis" aria-label="סקירת הוצאות"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 19V5"/><path d="M4 19h16"/><path d="M8 16v-5"/><path d="M12 16V8"/><path d="M16 16v-3"/></svg><span>סקירה</span></button></div>
<section class="card exp-hero"><div class="exp-monthnav"><button type="button" class="exp-navbtn" id="exp-prev" ${mi>=months.length-1?'disabled':''} aria-label="חודש קודם"><span aria-hidden="true">›</span></button><strong>${monthLabel(expenseMonth)}</strong><button type="button" class="exp-navbtn" id="exp-next" ${mi<=0?'disabled':''} aria-label="חודש הבא"><span aria-hidden="true">‹</span></button></div><div class="exp-total"><span>סה״כ החודש</span><strong dir="ltr">${formatCZK(total)}</strong><small>${list.length} הוצאות</small></div>${top.length?`<div class="exp-cats">${top.map(([id,v])=>{const c=catMeta(id);return `<div class="exp-cat"><span class="exp-cat-name">${c.icon} ${esc(c.label)}</span><span class="exp-cat-bar"><i style="width:${Math.max(4,Math.round(v/maxC*100))}%"></i></span><strong dir="ltr">${formatCZK(v)}</strong></div>`}).join('')}</div>`:''}</section>
<button type="button" class="primary exp-addbtn" id="exp-add-open">${svg('plus')}הוספת הוצאה</button>
<section class="card exp-list has-avo">${avoDeco('mark')}<div class="cardhead"><h2>פירוט החודש</h2><span class="sub">מהחדש לישן</span></div>${days.length?days.map(d=>`<div class="exp-day"><span>${formatDayLabel(d.date)}</span><span dir="ltr">${formatCZK(d.sum)}</span></div>${d.items.map(e=>{const c=catMeta(e.category);return `<div class="exp-row"><span class="exp-ico" aria-hidden="true">${c.icon}</span><div class="exp-main"><strong>${esc(e.title)}</strong><small>${esc(c.label)} · ${esc(whoName(e.who))}</small></div><strong class="exp-amt" dir="ltr">${formatCZK(e.amount)}</strong><button type="button" class="exp-del" data-del-exp="${e.id}" aria-label="מחיקת ${esc(e.title)}">${svg('close')}</button></div>`}).join('')}`).join(''):`<p class="listempty">${avoDeco('empty')}אין הוצאות בחודש הזה. מוסיפים עם הכפתור למעלה.</p>`}</section>`}
function openExpenseSheet(){let cat='super';const s=openSheet(`<h3>הוספת הוצאה</h3><label class="amountfield">כמה?<span class="amountwrap"><input id="exp-amount" type="number" inputmode="decimal" min="0" step="0.01" placeholder="0" dir="ltr" autocomplete="off"><span>CZK</span></span></label><div class="fieldlab">על מה?</div><div class="catchips" role="radiogroup" aria-label="קטגוריה">${expenseCategories.map(c=>`<button type="button" role="radio" aria-checked="${c.id===cat}" data-pick-cat="${c.id}" class="${c.id===cat?'on':''}"><span aria-hidden="true">${c.icon}</span>${c.label}</button>`).join('')}</div><label><span>תיאור <span class="opt">(לא חובה)</span></span><input id="exp-title" maxlength="80" placeholder="למשל קניות שבועיות" autocomplete="off" enterkeyhint="done"></label><div class="formrow"><label>תאריך<input id="exp-date" type="date" value="${expenseMonth===currentMonthKey()?todayISO():expenseMonth+'-01'}"></label><label>מי שילם?<select id="exp-who">${whoOptions(myMember().key,true)}</select></label></div><p class="formerror" id="exp-error" role="alert"></p><div class="sheet-actions"><button class="primary" id="exp-save">שמירת הוצאה</button><button class="secondary" id="exp-cancel">ביטול</button></div>`,'הוספת הוצאה');
  s.querySelectorAll('[data-pick-cat]').forEach(b=>b.onclick=()=>{cat=b.dataset.pickCat;s.querySelectorAll('[data-pick-cat]').forEach(x=>{const on=x.dataset.pickCat===cat;x.classList.toggle('on',on);x.setAttribute('aria-checked',on)})});
  const saveExp=()=>{const amount=Number($('#exp-amount').value);const date=$('#exp-date').value||todayISO();if(!Number.isFinite(amount)||amount<=0||amount>9999999){$('#exp-error').textContent='כמה זה עלה? כתבו סכום גדול מאפס.';$('#exp-amount').focus();return}if(!/^\d{4}-\d{2}-\d{2}$/.test(date)){$('#exp-error').textContent='בחרו תאריך.';return}const title=$('#exp-title').value.trim()||catMeta(cat).label;ensureExpenses();data.expenses.push({id:newId(),date,title:title.slice(0,80),amount:Math.round(amount*100)/100,category:cat,who:$('#exp-who').value});expenseMonth=monthKeyFromISO(date);save();closeSheet();render();toast('ההוצאה נשמרה')};
  s.querySelector('#exp-save').onclick=saveExp;s.querySelector('#exp-cancel').onclick=closeSheet;s.querySelector('#exp-title').onkeydown=e=>{if(e.key==='Enter')saveExp()};s.querySelector('#exp-amount').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#exp-title').focus()}};setTimeout(()=>s.querySelector('#exp-amount')?.focus(),60)}
function bindExpenses(){if($('#exp-prev'))$('#exp-prev').onclick=()=>{const m=expenseMonths();const i=m.indexOf(expenseMonth);if(i<m.length-1){expenseMonth=m[i+1];render()}};
if($('#exp-next'))$('#exp-next').onclick=()=>{const m=expenseMonths();const i=m.indexOf(expenseMonth);if(i>0){expenseMonth=m[i-1];render()}};
if($('#exp-analysis'))$('#exp-analysis').onclick=()=>{expenseView='analysis';render()};
if($('#exp-back-month'))$('#exp-back-month').onclick=()=>{expenseView='month';render()};
document.querySelectorAll('[data-chart-type]').forEach(b=>b.onclick=()=>{expenseChartType=b.dataset.chartType;render()});
document.querySelectorAll('[data-chart-mode]').forEach(b=>b.onclick=()=>{expenseChartMode=b.dataset.chartMode;render()});
if($('#exp-add-open'))$('#exp-add-open').onclick=openExpenseSheet;
document.querySelectorAll('[data-del-exp]').forEach(b=>b.onclick=()=>{const e=data.expenses.find(x=>x.id===+b.dataset.delExp);if(!e)return;confirmSheet(`למחוק את "${e.title}" (${formatCZK(e.amount)})?`,'מחיקה',()=>{data.expenses=data.expenses.filter(x=>x.id!==e.id);save();render();toast('ההוצאה נמחקה')})})}

/* ---------- settings (demo; cloud version lives in cloud.js) ---------- */
const camBadge='<span class="prof-cam" aria-hidden="true"><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 8h3l2-2h6l2 2h3v11H4z"/><circle cx="12" cy="13.5" r="3.2"/></svg></span>';
function settings(){if(CASA_CLOUD.active)return CASA_CLOUD.settings();const me=data.profiles.roei;const bigAv=(me.photo&&photoTag(me.photo,'avatar profilephoto prof-av',me.name||''))||`<span class="avatar initials prof-av" aria-hidden="true">${esc((me.name||'?').charAt(0))}</span>`;return `<div class="pagehead"><h1 class="withicon">${avoDeco('tiny')}הגדרות</h1></div><div class="settings-stack v7set"><section class="setgroup profile-card has-avo">${avoDeco('mark')}<div class="prof-row"><button type="button" class="prof-photo" id="open-photo-menu" aria-label="שינוי תמונת פרופיל">${bigAv}${camBadge}</button><div class="prof-fields"><input id="profile-name" class="prof-name-input" maxlength="35" value="${esc(me.name)}" placeholder="השם שלך" autocomplete="given-name" aria-label="השם שלך"><small>הדגמה מקומית</small></div><button class="primary sm" id="save-profile">שמירה</button></div><p id="photo-error" role="alert"></p><input class="uploadinput" type="file" id="profile-photo" accept="image/*" hidden><div id="photo-menu" class="photo-sheet" hidden><div class="photo-sheet-inner" role="dialog" aria-label="שינוי תמונת פרופיל"><div class="photo-sheet-handle" aria-hidden="true"></div><h3>שינוי תמונה</h3><button type="button" id="photo-pick">בחירת תמונה</button>${me.photo?`<button type="button" class="dangerish" id="remove-photo">הסרת תמונה</button>`:'<button type="button" id="remove-photo" hidden disabled>הסרת תמונה</button>'}<button type="button" class="quiet" id="photo-cancel">ביטול</button></div></div></section><div class="setlabel">הבית</div><section class="setgroup" id="household-card"><div class="setrow"><label for="house-name-edit">שם</label><input id="house-name-edit" maxlength="80" value="${esc(data.houseName||'הבית שלנו')}" placeholder="משפחת כהן, המגניבים…"><button class="primary sm" id="save-house-name">שמירה</button></div><div class="setrow members-row"><span class="setrow-label">חברי הבית</span><div class="members-block">${`<div class="memberrow">${avatar('roei')}<span>${esc(me.name)} · את/ה</span></div><div class="memberrow">${avatar('maya')}<span>${esc(data.profiles.maya.name)}</span></div>`}</div></div><button type="button" class="setrow setlink" data-go="invite"><span>הזמנה לבית · QR</span>${svg('chev')}</button></section></div>`}

/* ---------- shell ---------- */
function go(p){if(p!==page){closeSheet();closePhotoView();if(p!=='shopping'){lastAddedId=null;pendingPhoto=null}if(p==='meal-edit'){const ex=editingMealId?getMenu().find(m=>m.id===editingMealId):null;dishDraftPhoto=ex?.photo||null}if(page==='supermarket')releaseWake();if(p!=='meals')menuEdit=false}page=p;render();resetScroll();requestAnimationFrame(()=>{resetScroll();requestAnimationFrame(resetScroll)})}
function render(){ensureV2();ensureShopping();ensureExpenses();const views={welcome,login,create,invite,accept,home,shopping,supermarket,tasks,meals,meal,'meal-edit':mealEdit,expenses,settings,...CASA_CLOUD.views};const bare=['welcome','login','create','invite','accept','settings','meal-edit','tasks','supermarket',...CASA_CLOUD.bare];const cloud=CASA_CLOUD.active,authPage=CASA_CLOUD.authPages.includes(page)||(!cloud&&['welcome','login'].includes(page));const chromeless=page==='supermarket';const showNav=!bare.includes(page);const bar=authPage||page==='welcome'?'':superBar();
app.innerHTML=`<main class="shell${authPage||page==='welcome'?' authshell':''}${page==='welcome'?' welcome-shell':''}${chromeless?' supershell':''}">${page==='welcome'||chromeless?'':(authPage?CASA_CLOUD.simpleHeader():appHeader())}${chromeless?'':(cloud?CASA_CLOUD.banner():(authPage?'':'<div class="demo">הדגמה מקומית · כל התוכן נתוני דוגמה · ללא חשבונות או סנכרון ענן</div>'))}${(views[page]||welcome)()}${!bare.includes(page)&&!cloud?'<div class="footnote">כל השינויים נשמרים במכשיר הזה בלבד. <button class="quiet" id="reset">איפוס נתוני הדוגמה</button></div>':''}</main>${showNav?nav():''}${bar}`;
document.body.classList.toggle('has-superbar',!!bar);document.body.classList.toggle('has-nav',showNav);bind();CASA_CLOUD.bind();bindV7();syncAppFrame();pinNav();if(CASA_CLOUD.bindPhotos)CASA_CLOUD.bindPhotos()}
function bindV7(){
  const nb=document.querySelector('.nav'),sbar=$('#superbar');if(sbar&&nb)sbar.style.setProperty('--navh',nb.offsetHeight+'px');
  if(page==='supermarket')holdWake();
  // home: events
  if($('#add-event'))$('#add-event').onclick=()=>openEventSheet(selectedDay||todayISO());
  if($('#add-event-day'))$('#add-event-day').onclick=()=>openEventSheet(selectedDay||todayISO());
  document.querySelectorAll('[data-del-event]').forEach(b=>b.onclick=()=>{const e=(data.calendar||[]).find(x=>String(x.id)===b.dataset.delEvent);if(!e)return;confirmSheet(`למחוק את "${e.title}" מהיומן?`,'מחיקה',()=>{data.calendar=data.calendar.filter(x=>x!==e);save();render();toast('האירוע נמחק')})});
  // add input: keep the whole add row above the keyboard
  const qi=$('#quick-item');if(qi){qi.addEventListener('focus',()=>keepVisible(qi.closest('.addbar')||qi.closest('.quick')||qi));}
  // shopping
  if($('#start-super'))$('#start-super').onclick=startSuper;
  if($('#add-photo'))$('#add-photo').onclick=async()=>{const url=await choosePhoto({max:1000,q:.85,limit:350*1024});if(!url)return;pendingPhoto=url;const keep=$('#quick-item')?.value||'';render();if($('#quick-item')){$('#quick-item').value=keep;$('#quick-item').focus({preventScroll:true})}};
  if($('#clear-pending-photo'))$('#clear-pending-photo').onclick=()=>{pendingPhoto=null;render()};
  if($('#justadded-photo'))$('#justadded-photo').onclick=()=>attachItemPhoto(lastAddedId);
  if($('#justadded-close'))$('#justadded-close').onclick=()=>{lastAddedId=null;render()};
  document.querySelectorAll('[data-item-photo]').forEach(b=>b.onclick=()=>{const t=data.shopping.find(x=>x.id===+b.dataset.itemPhoto);if(t&&t.photo)openPhotoView(t.photo,t.name,()=>attachItemPhoto(t.id));else attachItemPhoto(+b.dataset.itemPhoto)});
  document.querySelectorAll('.super-row .li-photo').forEach(img=>{img.onclick=e=>{e.preventDefault();e.stopPropagation();const row=img.closest('[data-super]');const t=data.shopping.find(x=>x.id===+(row&&row.dataset.super));if(t&&t.photo)openPhotoView(t.photo,t.name)}})
  document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{const t=data.shopping.find(x=>x.id===+b.dataset.removePhoto);if(t){const old=t.photo;delete t.photo;save();if(old)dropPhoto(old);render();toast('התמונה הוסרה')}});
  document.querySelectorAll('[data-del-item]').forEach(b=>b.onclick=()=>{const id=+b.dataset.delItem;const gone=data.shopping.find(x=>x.id===id);data.shopping=data.shopping.filter(x=>x.id!==id);editingCategory=null;if(lastAddedId===id)lastAddedId=null;save();if(gone?.photo)dropPhoto(gone.photo);render();toast('הפריט הוסר מהרשימה')});
  // supermarket
  document.querySelectorAll('[data-super]').forEach(b=>b.onclick=()=>toggleShopping(+b.dataset.super));
  if($('#super-minimize'))$('#super-minimize').onclick=()=>go('shopping');
  if($('#super-end'))$('#super-end').onclick=()=>{const n=data.shopping.filter(t=>t.done).length;const s=openSheet(`<h3>לסיים את הקנייה?</h3><p class="sub">${n?`${n} פריטים סומנו בקו.`:'לא סומן אף פריט.'}</p><div class="sheet-actions">${n?`<button class="primary" id="end-clear">סיום והורדת מה שסומן</button><button class="secondary" id="end-keep">סיום בלי להוריד</button>`:`<button class="primary" id="end-keep">סיום</button>`}<button class="quiet" id="end-cancel">ממשיכים לקנות</button></div>`,'סיום הקנייה');s.querySelector('#end-clear')?.addEventListener('click',()=>endSuper(true));s.querySelector('#end-keep').onclick=()=>endSuper(false);s.querySelector('#end-cancel').onclick=closeSheet};
  // menu
  if($('#menu-edit-toggle'))$('#menu-edit-toggle').onclick=()=>{menuEdit=!menuEdit;render()};
  ['#menu-add','#menu-add-2'].forEach(s=>{if($(s))$(s).onclick=()=>{editingMealId=null;go('meal-edit')}});
  document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>moveDish(b.dataset.move,+b.dataset.dir));
  document.querySelectorAll('[data-move-cat]').forEach(s=>s.onchange=()=>moveDishToCategory(s.dataset.moveCat,s.value));
  document.querySelectorAll('[data-del-dish]').forEach(b=>b.onclick=()=>{const m=getMenu().find(x=>x.id===b.dataset.delDish);if(!m)return;confirmSheet(`למחוק את "${m.title}" מהתפריט?`,'מחיקה',()=>{deleteDish(m.id);render();toast('המנה נמחקה')})});
  if($('#dish-photo-pick'))$('#dish-photo-pick').onclick=async()=>{const url=await choosePhoto({max:1600,q:.9,limit:400*1024});if(!url)return;dishDraftPhoto=url;const b=$('#dish-photo-pick');if(b){b.classList.add('has');b.innerHTML=photoPickInner();b.setAttribute('aria-label','החלפת תמונת המנה')}const er=$('#dish-photo-error');if(er)er.textContent=''};
  if($('#save-dish'))$('#save-dish').onclick=async()=>{const title=$('#dish-title').value.trim();const existing=editingMealId?getMenu().find(m=>m.id===editingMealId):null;if(!dishDraftPhoto&&!existing){$('#dish-photo-error').textContent='צריך תמונה אמיתית של המנה — מצלמים או בוחרים מהגלריה.';$('#dish-photo-pick').scrollIntoView({block:'center',behavior:'smooth'});return}if(!title){toast('צריך שם למנה');$('#dish-title').focus();return}const ingredients=[...document.querySelectorAll('.ing-input')].map(i=>i.value.trim()).filter(Boolean);ensureMenu();const cat=$('#dish-category').value;const payload={...(existing||{}),id:existing?existing.id:('dish'+newId()),title,category:cat,time:Math.max(1,Math.min(240,Number($('#dish-time').value)||20)),note:$('#dish-note').value.trim(),instructions:$('#dish-instructions').value.trim(),ingredients};if(dishDraftPhoto){const isNew=typeof dishDraftPhoto==='string'&&dishDraftPhoto.startsWith('data:');payload.photo=isNew?await storePhoto(dishDraftPhoto):dishDraftPhoto;if(isNew&&existing?.photo&&existing.photo!==payload.photo)dropPhoto(existing.photo)}delete payload.art;if(!existing||existing.category!==cat){normalizeOrder(cat);payload.order=menuSorted(cat).filter(x=>x.id!==payload.id).length}const idx=data.menu.findIndex(m=>m.id===payload.id);const prev=idx>=0?data.menu[idx]:null;if(idx>=0)data.menu[idx]=payload;else data.menu.push(payload);if(!save()){if(prev)data.menu[idx]=prev;else data.menu.pop();return}editingMealId=null;menuCategory=cat;selectedMeal=payload.id;go('meal');toast('המנה נשמרה')};
  if($('#delete-dish'))$('#delete-dish').onclick=()=>{const id=editingMealId;const m=getMenu().find(x=>x.id===id);if(!m)return;confirmSheet(`למחוק את "${m.title}" מהתפריט?`,'מחיקה',()=>{deleteDish(id);editingMealId=null;go('meals');toast('המנה נמחקה')})};
}
CASA_CLOUD.boot();
